CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE,verified INTEGER NOT NULL DEFAULT 0,display_name TEXT NOT NULL,profile TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','SUPPORT','MODERATOR','ADMIN')),banned INTEGER NOT NULL DEFAULT 0,suspended_until TEXT,created_at TEXT NOT NULL,guest_expires_at TEXT);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE email_tokens(token_hash TEXT PRIMARY KEY,email TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE oauth_identities(provider TEXT NOT NULL,subject TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(provider,subject),UNIQUE(user_id,provider));
CREATE TABLE oauth_flows(state_hash TEXT PRIMARY KEY,browser_hash TEXT NOT NULL,nonce TEXT NOT NULL,code_verifier TEXT NOT NULL,session_hash TEXT,user_id TEXT,room_token TEXT,create_room INTEGER NOT NULL DEFAULT 0,expires_at TEXT NOT NULL);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
CREATE TABLE room_index(id TEXT PRIMARY KEY,type TEXT NOT NULL,creator_id TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,last_activity TEXT NOT NULL,expires_at TEXT,purge_at TEXT,version INTEGER NOT NULL,data TEXT NOT NULL);
CREATE INDEX discovery ON room_index(type,state,created_at DESC,id DESC);
CREATE TABLE membership_index(room_id TEXT NOT NULL,user_id TEXT NOT NULL,state TEXT NOT NULL,PRIMARY KEY(room_id,user_id));
CREATE INDEX memberships_user ON membership_index(user_id,state);
CREATE TABLE invite_index(token_hash TEXT PRIMARY KEY,room_id TEXT NOT NULL);
CREATE TABLE entity_index(id TEXT PRIMARY KEY,room_id TEXT NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX entities_room ON entity_index(room_id,kind);
CREATE TABLE blocks(user_id TEXT NOT NULL REFERENCES users(id),target_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(user_id,target_id),CHECK(user_id<>target_id));
CREATE TABLE social_requests(id TEXT PRIMARY KEY,requester_id TEXT NOT NULL REFERENCES users(id),target_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,source_room_id TEXT,state TEXT NOT NULL DEFAULT 'PENDING',result_room_id TEXT,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE UNIQUE INDEX pending_requests ON social_requests(requester_id,target_id,kind) WHERE state='PENDING';
CREATE TABLE contacts(user_a TEXT NOT NULL REFERENCES users(id),user_b TEXT NOT NULL REFERENCES users(id),room_id TEXT NOT NULL,PRIMARY KEY(user_a,user_b),CHECK(user_a<user_b));
CREATE TABLE match_history(user_a TEXT NOT NULL REFERENCES users(id),user_b TEXT NOT NULL REFERENCES users(id),room_id TEXT,matched_at TEXT NOT NULL,PRIMARY KEY(user_a,user_b));
CREATE TABLE active_matches(user_id TEXT PRIMARY KEY,room_id TEXT NOT NULL);
CREATE TABLE reports(id TEXT PRIMARY KEY,reporter_id TEXT,target_id TEXT,room_id TEXT,message_id TEXT,reason TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'OPEN',created_at TEXT NOT NULL);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,target_id TEXT,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE operations(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'PENDING',created_at TEXT NOT NULL);
CREATE TABLE app_outbox(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
